@extends('admin.layout') @section('title','Rendez-vous') @section('heading','Agenda & rendez-vous') @section('content')<section class="panel"><h2>Notifications récentes <span class="status">{{ $unreadCount }} non lue(s)</span></h2>@forelse($notifications as $notification)<div class="row" style="padding:9px 0;border-bottom:1px solid #eee"><div style="flex:1"><strong>{{ $notification->title }}</strong> @if(!$notification->read_at)<span class="status">Nouveau</span>@endif<br><span class="muted">{{ $notification->message }} · {{ $notification->created_at->format('d/m/Y H:i') }}</span></div>@if(!$notification->read_at)<form method="post" action="{{ route('admin.notifications.read',$notification) }}">@csrf<button class="secondary">Marquer comme lue</button></form>@endif</div>@empty<p class="muted">Aucune notification pour le moment.</p>@endforelse</section><section class="panel"><form class="row" method="get"><div><label>Date</label><input type="date" name="date" value="{{ request('date') }}"></div><div><label>Statut</label><select name="status"><option value="">Tous</option>@foreach(['pending','confirmed','completed','cancelled','rejected','no_show'] as $st)<option value="{{ $st }}" @selected(request('status')===$st)>{{ ['pending'=>'En attente','confirmed'=>'Confirmé','completed'=>'Terminé','cancelled'=>'Annulé','rejected'=>'Refusé','no_show'=>'Absence'][$st] }}</option>@endforeach</select></div><button>Filtrer</button><a href="{{ route('admin.bookings.index') }}">Réinitialiser</a></form></section><section class="panel"><div class="scroll"><table><thead><tr><th>Date & heure</th><th>Cliente / contact</th><th>Prestation</th><th>Mode / total</th><th>État & action</th></tr></thead><tbody>@forelse($bookings as $b)<tr><td><strong>{{ $b->appointment_date->format('d/m/Y') }}</strong><br>{{ substr($b->appointment_time,0,5) }}–{{ $b->ends_at?substr($b->ends_at,0,5):'—' }}<br><span class="muted">{{ $b->reference }}</span></td><td>{{ $b->customer_name }}<br><a href="mailto:{{ $b->customer_email }}">{{ $b->customer_email }}</a><br><a href="tel:{{ $b->customer_phone }}">{{ $b->customer_phone }}</a>@if($b->service_mode==='home')<br><span class="muted">{{ $b->address_line }}, {{ $b->postal_code }} {{ $b->city }}</span>@endif</td><td>{{ $b->service?->name }}<br><span class="muted">{{ $b->service_price }} € + {{ $b->travel_fee }} € déplacement</span></td><td>{{ $b->service_mode==='home'?'Domicile':'Salon' }}<br><strong>{{ number_format($b->total_price,2,',',' ') }} €</strong></td><td><form method="post" action="{{ route('admin.bookings.update',$b) }}">@csrf @method('PUT')<select name="status">@foreach(['pending','confirmed','completed','cancelled','rejected','no_show'] as $st)<option value="{{ $st }}" @selected($b->status===$st)>{{ ['pending'=>'En attente','confirmed'=>'Confirmé','completed'=>'Terminé','cancelled'=>'Annulé','rejected'=>'Refusé','no_show'=>'Absence'][$st] }}</option>@endforeach</select><div class="formgrid" style="grid-template-columns:1fr 1fr"><div><label>Nouvelle date (report)</label><input type="date" name="appointment_date" min="{{ today()->toDateString() }}"></div><div><label>Nouvelle heure</label><input type="time" name="appointment_time"></div></div><textarea name="admin_note" rows="2" placeholder="Note interne">{{ $b->admin_note }}</textarea><button>Enregistrer / reporter</button></form></td></tr>@empty<tr><td colspan="5">Aucun rendez-vous trouvé.</td></tr>@endforelse</tbody></table></div><p>{{ $bookings->links() }}</p></section>@endsection
